function AuthPage({ register = false, redirect = '/app' }: { register?: boolean; redirect?: string }) {
  const [organizationName, setOrganizationName] = useState('');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  async function submit(e: React.FormEvent) {
    e.preventDefault(); setError(''); setBusy(true);
    try {
      if (register && password !== confirmPassword) throw Error('Las contraseñas no coinciden.');
      if (register && !localAuth) throw Error('El registro de organización aún no está configurado en AWS.');
      let result: any;
      if (localAuth) {
        const base = env.VITE_API_IDENTITY as string | undefined;
        if (!base) throw Error('No se configuró el servicio de identidad local.');
        const payload = register ? { organizationName, name, email, password } : { email, password };
        const response = await fetch(`${base.replace(/\/$/, '')}/auth/${register ? 'register' : 'login'}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
        result = await response.json().catch(() => ({}));
        if (!response.ok) throw Error(result.error || (response.status === 401 ? 'Correo o contraseña incorrectos.' : `No se pudo ${register ? 'crear la organización' : 'iniciar sesión'} (HTTP ${response.status}).`));
        localStorage.setItem('cloudportfolio.accessToken', result.accessToken);
        localStorage.setItem('cloudportfolio.user', JSON.stringify(result.user));
      } else {
        result = await signIn({ username: email, password });
        if (!result.isSignedIn) throw Error(`Cognito requiere completar este paso: ${result.nextStep.signInStep}.`);
      }
      navigate(redirect.startsWith('/app') ? redirect : '/app');
    } catch (e) { setError(e instanceof Error ? e.message : 'No se pudo completar la solicitud.'); }
    finally { setBusy(false); }
  }

  const canRegister = register && localAuth;
  return <div className="auth-page"><div className="auth-backdrop"/><div className="auth-side"><Brand light/><div className="auth-side-content"><div className="section-kicker">ASTRA · PROJECT PORTFOLIO MANAGEMENT</div><h1>{register ? 'Un espacio común para avanzar.' : 'La estrategia merece una ejecución clara.'}</h1><p>{register ? 'Crea una organización local para tu equipo y conecta iniciativas, personas y decisiones.' : 'Entra a tu espacio de trabajo y continúa conectando tus iniciativas con resultados.'}</p><div className="auth-side-art"><div className="auth-art-circle circle-a"/><div className="auth-art-circle circle-b"/><div className="auth-art-card"><span><ChartNoAxesCombined size={20}/></span><b>Visión de portafolio</b><small>Personas · Proyectos · Presupuesto</small><div className="auth-art-bars"><i/><i/><i/><i/><i/><i/><i/></div></div></div></div><span className="auth-side-foot">ASTRA ? Gestión de portafolios de proyectos</span></div><main className="auth-main"><a className="auth-back" href="/" onClick={e => { e.preventDefault(); navigate('/'); }}>← Volver al inicio</a><div className="auth-card"><div className="auth-mobile-brand"><Brand/></div><div className="auth-heading"><span className="section-kicker">{register ? 'NUEVA ORGANIZACIóN' : 'BIENVENIDO DE NUEVO'}</span><h2>{register ? 'Crea tu organización' : 'Inicia sesión'}</h2><p>{register ? (localAuth ? 'El entorno local creará un tenant privado y su cuenta administradora.' : 'El alta de organizaciones en AWS requiere verificación de correo y aprovisionamiento Cognito todavía no configurados.') : 'Ingresa con las credenciales de tu organización.'}</p></div>{register && !localAuth ? <div className="register-notice" role="status"><ShieldCheck size={21}/><div><b>Registro AWS pendiente de configuración</b><p>Este formulario no crea cuentas en AWS. Usa el flujo de acceso Cognito configurado por el administrador del entorno.</p></div></div> : <form onSubmit={submit}>
    {canRegister && <><label htmlFor="organization-name">Nombre de la organización</label><div className="auth-input"><Layers size={17}/><input id="organization-name" autoComplete="organization" required minLength={2} maxLength={100} value={organizationName} onChange={e => setOrganizationName(e.target.value)} placeholder="Equipo de estrategia"/></div><label htmlFor="auth-name">Tu nombre</label><div className="auth-input"><Users size={17}/><input id="auth-name" autoComplete="name" required minLength={2} maxLength={100} value={name} onChange={e => setName(e.target.value)} placeholder="Nombre y apellido"/></div></>}
    <label htmlFor="auth-email">Correo electrónico</label><div className="auth-input"><Users size={17}/><input id="auth-email" type="email" autoComplete="username" required maxLength={254} value={email} onChange={e => setEmail(e.target.value)} placeholder="nombre@organizacion.com" aria-describedby={error ? 'auth-error' : undefined}/></div>
    <label htmlFor="auth-password">Contraseña</label><div className="auth-input"><ShieldCheck size={17}/><input id="auth-password" type={showPassword ? 'text' : 'password'} autoComplete={register ? 'new-password' : 'current-password'} required minLength={register ? 12 : 1} maxLength={128} value={password} onChange={e => setPassword(e.target.value)} placeholder={register ? 'Mínimo 12 caracteres' : 'Ingresa tu contraseña'} aria-describedby={error ? 'auth-error' : canRegister ? 'password-help' : undefined}/>{<button type="button" className="password-toggle" onClick={() => setShowPassword(!showPassword)} aria-label={showPassword ? 'Ocultar contraseña' : 'Mostrar contraseña'}>{showPassword ? <EyeOff size={17}/> : <Eye size={17}/>}</button>}</div>
    {canRegister && <><label htmlFor="auth-confirm-password">Confirma la contraseña</label><div className="auth-input"><ShieldCheck size={17}/><input id="auth-confirm-password" type={showPassword ? 'text' : 'password'} autoComplete="new-password" required minLength={12} maxLength={128} value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} placeholder="Repite la contraseña" aria-describedby="password-help"/></div><p className="auth-help" id="password-help">Usa 12 a 128 caracteres con al menos una mayúscula, una minúscula y un número. La cuenta será ADMIN de la nueva organización.</p></>}
    {error && <p className="auth-error" id="auth-error" role="alert">{error}</p>}
    <button className="button button-primary auth-submit" disabled={busy || !email || !password || (canRegister && (!name || !organizationName || !confirmPassword))}>{busy ? <><span className="button-spinner"/>{register ? 'Creando espacio?' : 'Verificando acceso?'}</> : register ? 'Crear organización' : 'Iniciar sesión'}{!busy && <ArrowRight size={17}/>}</button>
    {!register && <p className="auth-secure"><ShieldCheck size={15}/> Conexión protegida ? Acceso de tu organización</p>}
  </form>}<div className="auth-switch">{register ? '?Ya tienes acceso?' : '?Aún no tienes una cuenta?'} <a href={register ? '/login' : '/register'}>{register ? 'Iniciar sesión' : 'Crear organización'}</a></div><p className="auth-legal">{register ? 'El registro local crea un tenant independiente; las credenciales nunca se guardan en el navegador.' : 'Al continuar, accedes a tu espacio de trabajo de ASTRA.'}</p></div></main></div>;
}
type Item = Record<string, unknown> & { pk?: string; sk?: string };
type Module = { key: string; path: string; title: string; icon: React.ComponentType<{ size?: number }>; fields: string[]; required: string[] };
const modules: Module[] = [
  { key: 'portfolio', path: 'portfolios', title: 'Portafolios', icon: Layers, fields: ['name', 'description', 'ownerId', 'status'], required: ['name'] },
  { key: 'project', path: 'projects', title: 'Proyectos', icon: FolderKanban, fields: ['name', 'portfolioId', 'ownerId', 'status', 'startDate', 'endDate'], required: ['name'] },
  { key: 'resource', path: 'resources', title: 'Recursos', icon: Users, fields: ['name', 'type', 'capacity', 'status'], required: ['name'] },
  { key: 'budget', path: 'budgets', title: 'Presupuestos', icon: Wallet, fields: ['projectId', 'allocated', 'spent', 'currency'], required: ['projectId'] },
  { key: 'priority', path: 'priorities', title: 'Prioridades', icon: ArrowUpDown, fields: ['projectId', 'impact', 'urgency', 'risk', 'alignment'], required: ['projectId'] },
  { key: 'identity', path: 'users', title: 'Usuarios', icon: Users, fields: ['name', 'email', 'role', 'status'], required: ['name'] },
];

async function request<T = any>(module: string, path: string, method = 'GET', body?: unknown): Promise<T> {
  const session = localAuth ? undefined : await fetchAuthSession();
  const token = localAuth ? localStorage.getItem('cloudportfolio.accessToken') : session?.tokens?.idToken?.toString();
  if (!token) throw Error('La sesión expiró. Inicia sesión nuevamente.');
  const base = env[`VITE_API_${module.toUpperCase()}`] as string | undefined;
  if (!base) throw Error(`Falta configurar VITE_API_${module.toUpperCase()}`);
  const response = await fetch(`${base.replace(/\/$/, '')}/${path}`, { method, headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: body === undefined ? undefined : JSON.stringify(body) });
  const content = await response.json().catch(() => ({}));
  if (!response.ok) throw Error(content.error || `Solicitud fallida (HTTP ${response.status})`);
  return content as T;
}
function itemId(item: Item) { return typeof item.sk === 'string' ? item.sk.replace(/^ITEM#/, '') : ''; }
function DataTable({ title, rows, fields }: { title: string; rows: Item[]; fields: string[] }) { return <section className="panel"><h2>{title}</h2><div className="tableWrap"><table><thead><tr>{fields.map(f=><th key={f}>{f}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={itemId(row)||i}>{fields.map(f=><td key={f}>{readable(row[f])}</td>)}</tr>)}</tbody></table>{!rows.length&&<div className="empty">No hay registros todavía.</div>}</div></section>; }
function readable(value: unknown) { return value === undefined || value === null || value === '' ? '—' : String(value); }

function NotificationCenter() {
  const [prefs, setPrefs] = useState<any>({ enabled: false, timezone: 'America/Lima', allowedHours: { start: '08:00', end: '18:00' }, frequency: 'immediate', alertTypes: [], whatsappConsent: false });
  const [inbox, setInbox] = useState<any[]>([]); const [phone, setPhone] = useState(''); const [code, setCode] = useState(''); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  const types = ['ProjectCreated','ProjectUpdated','ProjectCompleted','BudgetThresholdExceeded','ResourceAssigned','PriorityRecalculated'];
  const load = useCallback(async () => { const [p, i] = await Promise.all([request('identity','notifications/preferences'),request<any>('identity','notifications/inbox')]); setPrefs(p); setInbox(i.items || []); }, []);
  useEffect(() => { void load().catch(e => setMessage(e instanceof Error ? e.message : String(e))); }, [load]);
  async function save(e:React.FormEvent) { e.preventDefault(); setBusy(true); setMessage(''); try { await request('identity','notifications/preferences','PUT',prefs); await load(); setMessage('Preferencias guardadas para tu usuario autenticado.'); } catch(e) { setMessage(e instanceof Error?e.message:String(e)); } finally { setBusy(false); } }
  async function startVerification() { setBusy(true); setMessage(''); try { const result=await request<any>('identity','notifications/whatsapp/verification','POST',{phoneNumber:phone,consent:Boolean(prefs.whatsappConsent)}); setMessage(result.message); const inboxCode=await request<any>('identity','notifications/verification-inbox'); setCode(inboxCode.code || ''); } catch(e) { setMessage(e instanceof Error?e.message:String(e)); } finally { setBusy(false); } }
  async function confirm() { setBusy(true); try { const result=await request<any>('identity','notifications/whatsapp/confirm','POST',{code}); setMessage(result.notice); await load(); } catch(e) { setMessage(e instanceof Error?e.message:String(e)); } finally { setBusy(false); } }
  async function revoke() { setBusy(true); try { await request('identity','notifications/whatsapp/number','DELETE'); await load(); setPhone(''); setCode(''); setMessage('Consentimiento revocado y número eliminado.'); } catch(e) { setMessage(e instanceof Error?e.message:String(e)); } finally { setBusy(false); } }
  return <section className="panel notification-panel"><div className="panelHeading"><div><h2>Centro de notificaciones</h2><span>Preferencias personales y buzón de eventos del tenant.</span></div><span className="mode-chip">MODO LOCAL SIMULADO</span></div><form className="notification-form" onSubmit={save}><label className="check-label"><input type="checkbox" checked={Boolean(prefs.enabled)} onChange={e=>setPrefs({...prefs,enabled:e.target.checked})}/> Activar alertas en el buzón local</label><div className="notification-options"><label>Zona horaria<input value={prefs.timezone||'America/Lima'} onChange={e=>setPrefs({...prefs,timezone:e.target.value})}/></label><label>Horario permitido desde<input type="time" value={prefs.allowedHours?.start||'08:00'} onChange={e=>setPrefs({...prefs,allowedHours:{...prefs.allowedHours,start:e.target.value}})}/></label><label>Hasta<input type="time" value={prefs.allowedHours?.end||'18:00'} onChange={e=>setPrefs({...prefs,allowedHours:{...prefs.allowedHours,end:e.target.value}})}/></label><label>Frecuencia<select value={prefs.frequency||'immediate'} onChange={e=>setPrefs({...prefs,frequency:e.target.value})}><option value="immediate">Por evento</option><option value="daily">Resumen diario (scheduler pendiente)</option><option value="weekly">Resumen semanal (scheduler pendiente)</option></select></label></div><fieldset><legend>Eventos de interés</legend><div className="notification-types">{types.map(type=><label className="check-label" key={type}><input type="checkbox" checked={(prefs.alertTypes||[]).includes(type)} onChange={e=>setPrefs({...prefs,alertTypes:e.target.checked?[...new Set([...(prefs.alertTypes||[]),type])]:prefs.alertTypes.filter((x:string)=>x!==type)})}/>{type}</label>)}</div></fieldset><button className="secondary" disabled={busy}>Guardar preferencias</button></form><div className="notification-whatsapp"><h3>WhatsApp Business</h3><p>El modo local no envía mensajes ni verifica el número ante WhatsApp. El código de abajo es solo una simulación de desarrollo.</p><div className="notification-options"><label>Número en formato internacional E.164<input placeholder="+51987654321" value={phone||prefs.whatsappNumber||''} onChange={e=>setPhone(e.target.value)}/></label><label className="check-label"><input type="checkbox" checked={Boolean(prefs.whatsappConsent)} onChange={e=>setPrefs({...prefs,whatsappConsent:e.target.checked})}/> Doy consentimiento para configurar este canal</label></div><div className="notification-actions"><button className="secondary" disabled={busy||!prefs.whatsappConsent} onClick={()=>void startVerification()}>Generar verificación local</button>{code&&<><label>Código local<input value={code} onChange={e=>setCode(e.target.value)}/></label><button className="secondary" disabled={busy} onClick={()=>void confirm()}>Confirmar simulación</button></>}<button className="textButton" disabled={busy} onClick={()=>void revoke()}>Revocar y eliminar número</button></div></div>{message&&<p className="assistant-state" role="status">{message}</p>}<div className="notification-inbox"><h3>Buzón local <small>Simulado localmente — No enviado a WhatsApp</small></h3>{inbox.length?inbox.slice(0,8).map((item:any)=><article key={item.eventId}><b>{item.title}</b><span>{item.createdAt}</span></article>):<p>No hay notificaciones locales para esta cuenta.</p>}</div></section>;
}

function OrbitalActionsPanel() {
  const [text, setText] = useState('Recuérdame revisar el presupuesto mañana a las 09:00'); const [recurrence, setRecurrence] = useState('ONCE');
  const [proposal, setProposal] = useState<any>(null); const [items, setItems] = useState<any[]>([]); const [actions, setActions] = useState<any[]>([]); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { const [r, a] = await Promise.all([request<any>('identity', 'reminders'), request<any>('identity', 'intelligence/actions')]); setItems(r.items || []); setActions(a.items || []); }, []);
  useEffect(() => { void load().catch((e) => setMessage(e instanceof Error ? e.message : String(e))); }, [load]);
  async function propose(e: React.FormEvent) { e.preventDefault(); setBusy(true); setProposal(null); setMessage(''); try { const result = await request<any>('identity', 'intelligence/proposals', 'POST', { text, recurrence, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/Lima' }); setProposal(result.proposal); } catch (e) { setMessage(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); } }
  async function confirmProposal() { if (!proposal) return; setBusy(true); try { const operationId = crypto.randomUUID(); const result = await request<any>('identity', `intelligence/actions/${encodeURIComponent(proposal.id)}/confirm`, 'POST', { operationId }); setMessage(proposal.kind==='TASK_CREATE'?`Tarea creada: ${result.task.title}`:`Recordatorio persistido: ${result.reminder.title}`); setProposal(null); await load(); } catch (e) { setMessage(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); } }
  async function setStatus(item: any, status: string) { setBusy(true); try { await request('identity', `reminders/${encodeURIComponent(item.id)}`, 'PATCH', { status }); await load(); } catch (e) { setMessage(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); } }
  async function cancel(item: any) { setBusy(true); try { await request('identity', `reminders/${encodeURIComponent(item.id)}`, 'DELETE'); await load(); } catch (e) { setMessage(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); } }
  return <section className="panel orbital-actions"><div className="panelHeading"><div><h2><CalendarDays size={18}/> Acciones y recordatorios</h2><span>El modo local entiende plantillas limitadas y pide confirmación antes de escribir.</span></div><span className="mode-chip">REGLAS DETERMINISTAS</span></div><form className="assistant-form" onSubmit={propose}><label className="sr-only" htmlFor="reminder-prompt">Solicitud para ASTRA</label><input id="reminder-prompt" maxLength={300} value={text} onChange={e=>setText(e.target.value)} aria-describedby="reminder-format"/><label className="sr-only" htmlFor="reminder-recurrence">Frecuencia del recordatorio</label><select id="reminder-recurrence" value={recurrence} onChange={e=>setRecurrence(e.target.value)}><option value="ONCE">Una vez</option><option value="DAILY">Diario</option><option value="WEEKLY">Semanal</option></select><button className="primary" disabled={busy}>{busy?'Interpretando…':'Proponer'}</button></form><small id="reminder-format">Recordatorio: “Recuérdame revisar el proyecto mañana a las 09:00”. Tarea: Crear tarea "Preparar cronograma" en proyecto &lt;ID&gt;. Se usa tu zona horaria: {Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/Lima'}.</small>{proposal&&<article className="action-proposal"><b>Propuesta pendiente de confirmación · {proposal.kind==='TASK_CREATE'?'Crear tarea':'Crear recordatorio'}</b><span>{proposal.title}{proposal.projectName?` · proyecto ${proposal.projectName}`:''}{proposal.dueAt?` · ${new Date(proposal.dueAt).toLocaleString()} · ${proposal.recurrence}`:''}</span><button className="primary" disabled={busy} onClick={()=>void confirmProposal()}>{proposal.kind==='TASK_CREATE'?'Confirmar y crear tarea':'Confirmar y programar'}</button><button className="textButton" disabled={busy} onClick={()=>setProposal(null)}>Descartar</button></article>}{message&&<p className="assistant-state" role="status">{message}</p>}<div className="orbital-reminder-list"><h3>Recordatorios e historial</h3>{items.length?items.map(item=><article key={item.id}><div><b>{item.title}</b><span>{new Date(item.dueAt).toLocaleString()} · {item.recurrence} · {item.status}</span></div>{item.status==='SCHEDULED'?<button className="textButton" disabled={busy} onClick={()=>void setStatus(item,'PAUSED')}>Pausar</button>:item.status==='PAUSED'?<button className="textButton" disabled={busy} onClick={()=>void setStatus(item,'SCHEDULED')}>Reanudar</button>:null}{['SCHEDULED','PAUSED'].includes(item.status)&&<button className="textButton" disabled={busy} onClick={()=>void cancel(item)}>Cancelar</button>}</article>):<p>No hay recordatorios. Las entregas aparecerán en el buzón local cuando venza la fecha.</p>}</div><details className="orbital-action-history"><summary>Historial de propuestas ({actions.length})</summary>{actions.map(item=><article key={item.id}><b>{item.title}</b><span>{item.status} · {item.confirmedAt||item.createdAt}</span></article>)}</details><small>Entrega local persistente: “Simulado localmente — No enviado a WhatsApp”.</small></section>;
}

function ReportsPanel() {
  const [type, setType] = useState('project-progress'); const [reports, setReports] = useState<any[]>([]); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  const types: Record<string,string> = {'portfolio-status':'Estado de portafolios','project-progress':'Avance de proyectos','overdue-tasks':'Tareas vencidas','resource-usage':'Uso de recursos','budgets':'Presupuestos','priorities':'Prioridades','risks':'Riesgos'};
  const load = useCallback(async()=>{const data=await request<any>('project','intelligence/reports');setReports(data.items||[]);},[]);
  useEffect(()=>{void load().catch(e=>setMessage(e instanceof Error?e.message:String(e)));},[load]);
  async function download(id:string) { const data=await request<any>('project',`intelligence/reports/${encodeURIComponent(id)}`); const report=data.report; const blob=new Blob([report.csv],{type:report.mediaType}); const url=URL.createObjectURL(blob); const link=document.createElement('a');link.href=url;link.download=report.fileName;link.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000); }
  async function generate(e:React.FormEvent){e.preventDefault();setBusy(true);setMessage('');try{const data=await request<any>('project','intelligence/reports','POST',{type});setMessage(`${data.report.rows.length} filas. Alcance: hasta 1 000 resultados por servicio${data.report.scope.truncated?.length ? ' (truncado)' : ''}${data.report.unavailable?.length ? '; algunos servicios no disponibles' : ''}.`);await load();await download(data.report.id);}catch(e){setMessage(e instanceof Error?e.message:String(e));}finally{setBusy(false);}}
  return <section className="panel report-panel"><div className="panelHeading"><div><h2><BarChart3 size={18}/> Reportes</h2><span>Consultas tenant-scoped a servicios de dominio; cada reporte persiste su alcance y filas.</span></div><span className="mode-chip">CSV</span></div><form className="assistant-form" onSubmit={generate}><label className="sr-only" htmlFor="report-type">Tipo de reporte</label><select id="report-type" value={type} onChange={e=>setType(e.target.value)}>{Object.entries(types).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><button className="primary" disabled={busy}>{busy?'Generando…':'Generar CSV'}</button></form>{message&&<p className="assistant-state" role="status">{message}</p>}<div className="orbital-reminder-list"><h3>Historial persistido</h3>{reports.map(report=><article key={report.id}><div><b>{types[report.type]||report.type}</b><span>{report.generatedAt} · {report.scope?.partial?'alcance parcial':'alcance visible'}</span></div><button className="textButton" disabled={busy} onClick={()=>void download(report.id)}>Descargar CSV</button></article>)}{!reports.length&&<p>No se han generado reportes en esta organización.</p>}</div><small>Se recorren hasta 10 páginas (máximo 1 000 resultados por servicio); el reporte indica si el alcance quedó truncado. Los importes no se convierten entre monedas; aún no hay filtros personalizados ni PDF.</small></section>;
}

function Dashboard() {
  const [user, setUser] = useState(''); const [refreshToken, setRefreshToken] = useState(0);
  const [assistantQuestion, setAssistantQuestion] = useState(''); const [assistantAnswer, setAssistantAnswer] = useState<any>(null); const [assistantBusy, setAssistantBusy] = useState(false);
  const appPath=usePathname(); const routeTabs:Record<string,string>={portfolios:'portfolio',projects:'project',resources:'resource',budgets:'budget',priorities:'priority'}; const tabRoutes:Record<string,string>={dashboard:'/app',portfolio:'/app/portfolios',project:'/app/projects',resource:'/app/resources',budget:'/app/budgets',priority:'/app/priorities',tasks:'/app/projects',assignments:'/app/resources',expenses:'/app/budgets',rankings:'/app/priorities'}; const initialSegment=window.location.pathname.split('/')[2]||''; const [tab,setTab]=useState(routeTabs[initialSegment]||'dashboard'); function selectTab(next:string){setTab(next);const route=tabRoutes[next]||'/app';if(window.location.pathname!==route)navigate(route);} useEffect(()=>{const segment=appPath.split('/')[2]||'';setTab(routeTabs[segment]||'dashboard');},[appPath]); const [items, setItems] = useState<Item[]>([]); const [form, setForm] = useState<Record<string, string>>({});
  const [editing, setEditing] = useState<Item | null>(null); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [busy, setBusy] = useState(false); const [cursor, setCursor] = useState<string | null>(null); const [search, setSearch] = useState('');
  const [overview, setOverview] = useState<Record<string, Item[]>>({});
  const [taskProjects, setTaskProjects] = useState<Item[]>([]); const [taskProject, setTaskProject] = useState(''); const [tasks, setTasks] = useState<Item[]>([]); const [taskTitle, setTaskTitle] = useState('');
  const [assignmentRows, setAssignmentRows] = useState<Item[]>([]); const [resourceRows, setResourceRows] = useState<Item[]>([]); const [projectRows, setProjectRows] = useState<Item[]>([]); const [assignmentForm, setAssignmentForm] = useState({ resourceId: '', projectId: '', allocation: '0.5' });
  const [budgetRows, setBudgetRows] = useState<Item[]>([]); const [expenseRows, setExpenseRows] = useState<Item[]>([]); const [expenseForm, setExpenseForm] = useState({ budgetId: '', description: '', amount: '', currency: 'USD' }); const [rankingRows, setRankingRows] = useState<Item[]>([]); const [priorityForm, setPriorityForm] = useState({ projectId: '', impact: '50', urgency: '50', risk: '50', alignment: '50' });
  const active = modules.find(m => m.key === tab); const dashboard = tab === 'dashboard';
  useEffect(() => {
    if (localAuth) { const stored = localStorage.getItem('cloudportfolio.user'); if (stored) { try { setUser(JSON.parse(stored).email); } catch { localStorage.removeItem('cloudportfolio.user'); } } }
    else getCurrentUser().then(u => setUser(u.username)).catch(() => undefined);
  }, []);

  const load = useCallback(async (next?: string) => {
    if (!active) return;
    setBusy(true); setError('');
    try { const data = await request<{ items: Item[]; nextCursor: string | null }>(active.key, `${active.path}${next ? `?cursor=${encodeURIComponent(next)}` : ''}`); setItems(next ? old => [...old, ...data.items] : data.items); setCursor(data.nextCursor); }
    catch (e) { setError(e instanceof Error ? e.message : String(e)); }
    finally { setBusy(false); }
  }, [active]);
  const loadOverview = useCallback(async () => {
    setBusy(true); setError('');
    try {
      const results = await Promise.all(modules.map(async m => [m.key, (await request<{ items: Item[] }>(m.key, m.path)).items] as const));
      setOverview(Object.fromEntries(results));
    } catch (e) { setError(e instanceof Error ? e.message : String(e)); }
    finally { setBusy(false); }
  }, []);
  useEffect(() => { if (!user) return; setSearch(''); if (dashboard) void loadOverview(); else void load(); }, [user, tab, dashboard, load, loadOverview, refreshToken]);
  useEffect(() => {
    if (!user) return;
    const rows = async (module: string, path: string) => (await request<{ items: Item[] }>(module, path)).items || [];
    if (tab === 'tasks') void rows('project', 'projects').then(data => { setTaskProjects(data); setTaskProject(current => current && data.some(p => itemId(p) === current) ? current : itemId(data[0] || {})); }).catch(e => setError(String(e)));
    if (tab === 'assignments') void Promise.all([rows('resource', 'assignments'), rows('resource', 'resources'), rows('project', 'projects')]).then(([a, r, p]) => { setAssignmentRows(a); setResourceRows(r); setProjectRows(p); }).catch(e => setError(String(e)));
    if (tab === 'expenses') void Promise.all([rows('budget', 'budgets'), rows('budget', 'expenses'), rows('project', 'projects')]).then(([b, x, p]) => { setBudgetRows(b.filter(i => i.entityType !== 'Expense')); setExpenseRows(x); setProjectRows(p); }).catch(e => setError(String(e)));
    if (tab === 'rankings') { void request<{ items: Item[] }>('priority', 'rankings').then(data => setRankingRows(data.items || [])).catch(e => setError(String(e))); void rows('project', 'projects').then(setProjectRows).catch(e => setError(String(e))); }
  }, [user, tab, refreshToken]);
  useEffect(() => { if (!taskProject || tab !== 'tasks') return; void request<{ items: Item[] }>('project', `projects/${encodeURIComponent(taskProject)}/tasks`).then(data => setTasks(data.items || [])).catch(e => setError(String(e))); }, [taskProject, tab, refreshToken]);

  function startCreate() { setEditing(null); setForm({}); setNotice(''); }
  function startEdit(item: Item) { const values: Record<string, string> = {}; active?.fields.forEach(field => { values[field] = item[field] == null ? '' : String(item[field]); }); setEditing(item); setForm(values); setNotice(''); }
  async function save(e: React.FormEvent) { e.preventDefault(); if (!active) return; setBusy(true); setError(''); setNotice('');
    try { const payload = Object.fromEntries(Object.entries(form).filter(([, v]) => v.trim()).map(([k, v]) => [k, ['allocated', 'spent', 'capacity', 'impact', 'urgency', 'risk', 'alignment'].includes(k) ? Number(v) : v]));
      if (editing) await request(active.key, `${active.path}/${encodeURIComponent(itemId(editing))}`, 'PATCH', payload); else await request(active.key, active.path, 'POST', payload);
      setForm({}); setEditing(null); setNotice(editing ? 'Cambios guardados.' : 'Registro creado.'); await load();
    } catch (e) { setError(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); }
  }
  async function remove(item: Item) { if (!active || !window.confirm(`¿Eliminar “${readable(item.name ?? item.projectId)}”?`)) return; setBusy(true); setError('');
    try { await request(active.key, `${active.path}/${encodeURIComponent(itemId(item))}`, 'DELETE'); setNotice('Registro eliminado.'); await load(); } catch (e) { setError(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); }
  }
  async function createTask(e: React.FormEvent) { e.preventDefault(); if (!taskProject) return; setBusy(true); setError(''); try { await request('project', `projects/${encodeURIComponent(taskProject)}/tasks`, 'POST', { title: taskTitle }); setTaskTitle(''); const data = await request<{ items: Item[] }>('project', `projects/${encodeURIComponent(taskProject)}/tasks`); setTasks(data.items || []); setNotice('Tarea creada.'); } catch (e) { setError(String(e)); } finally { setBusy(false); } }
  async function moveTask(task: Item, status: string) { try { await request('project', `projects/${encodeURIComponent(taskProject)}/tasks/${encodeURIComponent(String(task.id))}`, 'PATCH', { status }); setTasks(old => old.map(x => x.id === task.id ? { ...x, status } : x)); } catch (e) { setError(String(e)); } }
  async function createAssignment(e: React.FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { await request('resource', 'assignments', 'POST', { ...assignmentForm, allocation: Number(assignmentForm.allocation) }); const data = await request<{ items: Item[] }>('resource', 'assignments'); setAssignmentRows(data.items || []); setNotice('Asignación creada.'); } catch (e) { setError(String(e)); } finally { setBusy(false); } }
  async function createExpense(e: React.FormEvent) { e.preventDefault(); const budget = budgetRows.find(b => itemId(b) === expenseForm.budgetId); if (!budget) return; setBusy(true); setError(''); try { await request('budget', 'expenses', 'POST', { budgetId: expenseForm.budgetId, projectId: String(budget.projectId), description: expenseForm.description, amount: Number(expenseForm.amount), currency: expenseForm.currency }); const [expenses, budgets] = await Promise.all([request<any>('budget', 'expenses'), request<any>('budget', 'budgets')]); setExpenseRows(expenses.items || []); setBudgetRows((budgets.items || []).filter((x: Item) => x.entityType !== 'Expense')); setExpenseForm({ ...expenseForm, description: '', amount: '' }); setNotice('Gasto registrado.'); } catch (e) { setError(String(e)); } finally { setBusy(false); } }
  async function recalculatePriority(e: React.FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { await request('priority', 'priorities/recalculate', 'POST', { ...priorityForm, impact: Number(priorityForm.impact), urgency: Number(priorityForm.urgency), risk: Number(priorityForm.risk), alignment: Number(priorityForm.alignment) }); const data = await request<{ items: Item[] }>('priority', 'rankings'); setRankingRows(data.items || []); setNotice('Prioridad recalculada y ranking actualizado.'); } catch (e) { setError(String(e)); } finally { setBusy(false); } }
  async function askAssistant(question = assistantQuestion) { if (!question.trim()) return; setAssistantBusy(true); setAssistantAnswer(null); try { setAssistantAnswer(await request('project', 'intelligence/ask', 'POST', { question })); } catch (e) { setAssistantAnswer({ error: e instanceof Error ? e.message : String(e) }); } finally { setAssistantBusy(false); } }
  const specialView = tab === 'tasks' ? <><section className="panel"><h2>Tablero Kanban</h2><select value={taskProject} onChange={e=>setTaskProject(e.target.value)}><option value="">Selecciona proyecto</option>{taskProjects.map(p=><option key={itemId(p)} value={itemId(p)}>{readable(p.name)}</option>)}</select><form className="create" onSubmit={createTask}><label>Nueva tarea<input required value={taskTitle} onChange={e=>setTaskTitle(e.target.value)}/></label><button disabled={busy||!taskProject}><Plus size={16}/>Crear</button></form></section><div className="kanban">{[['TODO','Por hacer'],['IN_PROGRESS','En progreso'],['BLOCKED','Bloqueadas'],['DONE','Completadas']].map(([s,t])=><section className="kanbanColumn" key={s}><h2>{t}<span>{tasks.filter(x=>x.status===s).length}</span></h2>{tasks.filter(x=>x.status===s).map(x=><article className="taskCard" key={String(x.id)}><strong>{readable(x.title)}</strong><select value={String(x.status)} onChange={e=>void moveTask(x,e.target.value)}>{['TODO','IN_PROGRESS','BLOCKED','DONE'].map(v=><option key={v}>{v}</option>)}</select></article>)}</section>)}</div></> : tab === 'assignments' ? <><section className="panel"><h2>Asignar recurso a proyecto</h2><form className="create" onSubmit={createAssignment}><label>Recurso<select required value={assignmentForm.resourceId} onChange={e=>setAssignmentForm({...assignmentForm,resourceId:e.target.value})}><option value="">Selecciona</option>{resourceRows.map(x=><option key={itemId(x)} value={itemId(x)}>{readable(x.name)}</option>)}</select></label><label>Proyecto<select required value={assignmentForm.projectId} onChange={e=>setAssignmentForm({...assignmentForm,projectId:e.target.value})}><option value="">Selecciona</option>{projectRows.map(x=><option key={itemId(x)} value={itemId(x)}>{readable(x.name)}</option>)}</select></label><label>Asignación (%)<input type="number" min="1" max="100" value={Number(assignmentForm.allocation)*100} onChange={e=>setAssignmentForm({...assignmentForm,allocation:String(Number(e.target.value)/100)})}/></label><button disabled={busy}><UserPlus size={16}/>Asignar</button></form></section><DataTable title="Asignaciones" rows={assignmentRows} fields={['resourceId','projectId','allocation','startDate','endDate']}/></> : tab === 'expenses' ? <><section className="panel"><h2>Registrar gasto</h2><form className="create" onSubmit={createExpense}><label>Presupuesto<select required value={expenseForm.budgetId} onChange={e=>setExpenseForm({...expenseForm,budgetId:e.target.value})}><option value="">Selecciona</option>{budgetRows.map(x=><option key={itemId(x)} value={itemId(x)}>{readable(x.projectId)} · {readable(x.currency)}</option>)}</select></label><label>Descripción<input required value={expenseForm.description} onChange={e=>setExpenseForm({...expenseForm,description:e.target.value})}/></label><label>Importe<input required type="number" min="0.01" step="0.01" value={expenseForm.amount} onChange={e=>setExpenseForm({...expenseForm,amount:e.target.value})}/></label><button disabled={busy}><ReceiptText size={16}/>Registrar</button></form></section><DataTable title="Gastos recientes" rows={expenseRows} fields={['description','projectId','amount','currency','createdAt']}/></> : tab === 'rankings' ? <><section className="panel"><h2>Recalcular prioridad</h2><form className="create" onSubmit={recalculatePriority}><label>Proyecto<select required value={priorityForm.projectId} onChange={e=>setPriorityForm({...priorityForm,projectId:e.target.value})}><option value="">Selecciona</option>{projectRows.map(x=><option key={itemId(x)} value={itemId(x)}>{readable(x.name)}</option>)}</select></label>{(['impact','urgency','risk','alignment'] as const).map(k=><label key={k}>{k}<input type="number" min="0" max="100" value={priorityForm[k]} onChange={e=>setPriorityForm({...priorityForm,[k]:e.target.value})}/></label>)}<button disabled={busy}><ArrowUpDown size={16}/>Calcular</button></form></section><DataTable title="Ranking de proyectos" rows={rankingRows} fields={['rank','projectId','score','impact','urgency','risk','alignment']}/></> : null;
  const filtered = useMemo(() => items.filter(item => Object.values(item).some(v => String(v ?? '').toLowerCase().includes(search.toLowerCase()))), [items, search]);
  const projects = overview.project || []; const portfolios = overview.portfolio || []; const budgets = overview.budget || []; const priorities = overview.priority || [];
  const allocated = budgets.reduce((sum, b) => sum + (Number(b.allocated) || 0), 0); const spent = budgets.reduce((sum, b) => sum + (Number(b.spent) || 0), 0);
  return <div className="layout"><aside><h2><GalaxyGlyph/> ASTRA</h2><div className="sidebarLabel">ESPACIO DE TRABAJO</div><button className={`nav ${dashboard ? 'selected' : ''}`} onClick={() => selectTab('dashboard')}><ChartNoAxesCombined size={18} />Resumen ejecutivo</button><div className="sidebarLabel groupLabel">GESTIÓN</div>{modules.map(m => <button key={m.key} className={`nav ${tab === m.key ? 'selected' : ''}`} onClick={() => selectTab(m.key)}><m.icon size={18} />{m.title}</button>)}<div className="sidebarLabel groupLabel">OPERACION</div>{[['tasks','Kanban',ListTodo],['assignments','Asignaciones',UserPlus],['expenses','Gastos',ReceiptText],['rankings','Ranking',Trophy]].map(([key,label,Icon]: any)=><button key={key} className={`nav ${tab===key?'selected':''}`} onClick={()=>selectTab(key)}><Icon size={18}/>{label}</button>)}<div className="asideBottom"><div className="userBadge"><span>{user.slice(0, 1).toUpperCase()}</span><div><strong>{user}</strong><small>Sesión autenticada</small></div></div><button className="nav" onClick={async () => { if (localAuth) { localStorage.removeItem('cloudportfolio.accessToken'); localStorage.removeItem('cloudportfolio.user'); } else await signOut(); setUser(''); navigate('/'); }}><LogOut size={17} />Cerrar sesión</button></div></aside>
    <main><header><div><span className="eyebrow">ASTRA / {dashboard ? 'VISIÓN GENERAL' : (active?.title || ({tasks:'KANBAN',assignments:'ASIGNACIONES',expenses:'GASTOS',rankings:'RANKING'} as Record<string,string>)[tab]).toUpperCase()}</span><h1>{dashboard ? 'Resumen ejecutivo' : active?.title || ({tasks:'Tablero Kanban',assignments:'Asignaciones',expenses:'Gastos',rankings:'Ranking'} as Record<string,string>)[tab]}</h1><p>{dashboard ? 'Una vista rápida del estado de tu organización.' : `Consulta y administra ${(active?.title || tab).toLowerCase()} de tu organización.`}</p></div><button className="secondary" disabled={busy} onClick={() => setRefreshToken(n => n + 1)}><RefreshCw size={16} className={busy ? 'spin' : ''} />Actualizar</button></header>
      {error && <div className="error banner">{error}<button aria-label="Cerrar error" onClick={() => setError('')}><X size={16} /></button></div>}{notice && <div className="notice banner">{notice}<button aria-label="Cerrar aviso" onClick={() => setNotice('')}><X size={16} /></button></div>}
      {dashboard ? <><section className="stats"><article className="statCard"><span>Proyectos activos</span><strong>{projects.filter(p => !['completed', 'complete', 'done'].includes(String(p.status).toLowerCase())).length}</strong><small><FolderKanban size={15} /> {projects.length} proyectos registrados</small></article><article className="statCard"><span>Portafolios</span><strong>{portfolios.length}</strong><small><Layers size={15} /> Agrupación estratégica</small></article><article className="statCard"><span>Presupuesto asignado</span><strong>{allocated.toLocaleString('es-PE', { maximumFractionDigits: 0 })}</strong><small><Wallet size={15} /> Gastado: {spent.toLocaleString('es-PE', { maximumFractionDigits: 0 })}</small></article><article className="statCard"><span>Evaluaciones de prioridad</span><strong>{priorities.length}</strong><small><ArrowUpDown size={15} /> Priorización registrada</small></article></section>
        <section className="panel intelligence-panel" id="astra-intelligence"><div className="panelHeading"><div><h2><Sparkles size={18}/> Inteligencia ASTRA</h2><span>Consultas de solo lectura sobre APIs autorizadas de tu organización.</span></div><span className="mode-chip">REGLAS DETERMINISTAS</span></div><form className="assistant-form" onSubmit={e=>{e.preventDefault();void askAssistant();}}><label className="sr-only" htmlFor="assistant-question">Pregunta para Inteligencia ASTRA</label><input id="assistant-question" maxLength={500} value={assistantQuestion} onChange={e=>setAssistantQuestion(e.target.value)} placeholder="¿Qué proyectos están atrasados?"/><button className="primary" disabled={assistantBusy||!assistantQuestion.trim()}>{assistantBusy?'Consultando…':<>Consultar <ArrowRight size={15}/></>}</button></form><div className="assistant-prompts">{['¿Qué proyectos están atrasados?','¿Qué presupuesto está cerca de agotarse?','Resume mis prioridades'].map(q=><button key={q} onClick={()=>{setAssistantQuestion(q);void askAssistant(q);}}>{q}</button>)}</div>{assistantBusy&&<p className="assistant-state" role="status">Consultando las APIs de dominio con tu sesión…</p>}{assistantAnswer?.error&&<p className="error assistant-state" role="alert">{assistantAnswer.error}</p>}{assistantAnswer&&!assistantAnswer.error&&<div className="assistant-answer"><strong>Hechos consultados</strong><ul>{assistantAnswer.facts.map((fact:string,i:number)=><li key={i}>{fact}</li>)}</ul><strong>Sugerencias (no ejecutan cambios)</strong><ul>{assistantAnswer.suggestions.map((item:string,i:number)=><li key={i}>{item}</li>)}</ul>{assistantAnswer.relatedProjects?.length>0&&<><strong>Proyectos relacionados</strong><ul>{assistantAnswer.relatedProjects.map((item:any)=><li key={item.id}><a href="/app/projects">{item.name || item.id}</a> · {item.status} · cierre {item.endDate}</li>)}</ul></>}{assistantAnswer.relatedTasks?.length>0&&<><strong>Tareas para revisar</strong><ul>{assistantAnswer.relatedTasks.map((item:any)=><li key={item.id}><a href="/app/projects">{item.title || item.id}</a> · vence {item.dueDate}</li>)}</ul></>}<small>Alcance: primera página de hasta 100 resultados por dominio. {assistantAnswer.unavailable.length?`Servicios no disponibles: ${assistantAnswer.unavailable.join(', ')}.`:''}</small></div>}</section>
        <NotificationCenter/><OrbitalActionsPanel/><ReportsPanel/><section className="dashboardGrid"><div className="panel"><div className="panelHeading"><div><h2>Proyectos recientes</h2><span>Datos consultados desde Project Service</span></div><button className="textButton" onClick={() => selectTab('project')}>Ver proyectos →</button></div>{projects.length ? <div className="projectList">{projects.slice(0, 6).map((p, i) => <div className="projectRow" key={itemId(p) || i}><span className="projectIcon"><BriefcaseBusiness size={17} /></span><div className="projectName"><strong>{readable(p.name)}</strong><small>{readable(p.portfolioId)} · responsable {readable(p.ownerId)}</small></div><span className={`status status-${String(p.status || 'planning').toLowerCase()}`}>{readable(p.status || 'Planificación')}</span></div>)}</div> : <div className="empty">{busy ? 'Cargando información…' : 'Todavía no hay proyectos. Crea uno para comenzar.'}</div>}</div>
          <div className="panel budgetPanel"><div className="panelHeading"><div><h2>Salud presupuestaria</h2><span>Consolidado de los registros visibles</span></div><Wallet size={19} className="mutedIcon" /></div><strong className="budgetTotal">{spent.toLocaleString('es-PE')} <small>gastado</small></strong><div className="progressTrack"><span style={{ width: `${allocated > 0 ? Math.min(100, spent / allocated * 100) : 0}%` }} /></div><div className="budgetFoot"><span>Asignado <b>{allocated.toLocaleString('es-PE')}</b></span><span>{allocated > 0 ? Math.round(spent / allocated * 100) : 0}% utilizado</span></div><button className="textButton" onClick={() => selectTab('budget')}>Ver presupuestos →</button></div>
        </section><div className="dataNote"><Activity size={16} /> El resumen refleja los primeros resultados que devuelven las APIs (hasta 50 por servicio). Los importes usan la moneda indicada en cada presupuesto.</div></> : active ? <>
        <section className="stats compactStats"><article className="statCard"><span>Registros en esta página</span><strong>{items.length}</strong><small><Activity size={15} /> {cursor ? 'Hay más resultados disponibles' : 'Resultados del tenant autenticado'}</small></article><article className="statCard"><span>Servicio</span><strong className="serviceName">{active.key}-service</strong><small>API independiente</small></article><article className="statCard"><span>Acceso</span><strong className="serviceName">JWT protegido</strong><small>Aislamiento aplicado por el servicio</small></article></section>
        <section className="panel"><div className="panelHeading"><div><h2>{editing ? 'Editar registro' : 'Crear registro'}</h2><span>Los campos se validan según el contrato del servicio.</span></div>{editing && <button className="iconButton" onClick={startCreate} title="Cancelar edición"><X size={17} /></button>}</div><form className="create" onSubmit={save}>{active.fields.map(field => <label key={field}>{field}{active.required.includes(field) ? ' *' : ''}<input required={active.required.includes(field)} type={['allocated', 'spent', 'capacity', 'impact', 'urgency', 'risk', 'alignment'].includes(field) ? 'number' : field.endsWith('Date') ? 'date' : 'text'} step={['allocated', 'spent', 'capacity', 'impact', 'urgency', 'risk', 'alignment'].includes(field) ? 'any' : undefined} value={form[field] || ''} onChange={e => setForm({ ...form, [field]: e.target.value })} placeholder={field} /></label>)}<button disabled={busy}><Plus size={17} />{busy ? 'Guardando…' : editing ? 'Guardar cambios' : 'Crear registro'}</button></form></section>
        <section className="panel"><div className="panelHeading listHeading"><div><h2>Registros</h2><span>{filtered.length} visibles · resultados paginados por tenant</span></div><label className="searchBox"><Search size={16} /><input aria-label="Buscar registros" placeholder="Buscar…" value={search} onChange={e => setSearch(e.target.value)} /></label></div><div className="tableWrap"><table><thead><tr><th>Identificador</th>{active.fields.slice(0, 4).map(f => <th key={f}>{f}</th>)}<th>Acciones</th></tr></thead><tbody>{filtered.map((item, i) => <tr key={itemId(item) || i}><td className="idCell">{itemId(item).slice(0, 13) || '—'}</td>{active.fields.slice(0, 4).map(f => <td key={f}>{readable(item[f])}</td>)}<td><div className="rowActions"><button onClick={() => startEdit(item)}>Editar</button><button className="deleteAction" onClick={() => void remove(item)}>Eliminar</button></div></td></tr>)}</tbody></table>{!filtered.length && <div className="empty">{busy ? 'Cargando registros…' : search ? 'No hay resultados para esta búsqueda.' : 'No hay registros todavía. Crea uno para comenzar.'}</div>}</div>{cursor && <button className="secondary moreButton" disabled={busy} onClick={() => void load(cursor)}>Cargar más</button>}</section>
      </> : specialView}
    </main></div>;
}
function App() { const pathname=usePathname(); const [authenticated,setAuthenticated]=useState<boolean|null>(null); useEffect(()=>{if(authenticated&&(pathname==='/login'||pathname==='/register'))navigate('/app');},[authenticated,pathname]); useEffect(()=>{ let active=true; const check=async()=>{ if(localAuth){const ok=Boolean(localStorage.getItem('cloudportfolio.accessToken')&&localStorage.getItem('cloudportfolio.user'));if(active)setAuthenticated(ok);}else{try{await getCurrentUser();if(active)setAuthenticated(true);}catch{if(active)setAuthenticated(false);}}};void check();const onStorage=()=>void check();window.addEventListener('storage',onStorage);return()=>{active=false;window.removeEventListener('storage',onStorage);};},[pathname]);const protectedRoute=pathname==='/app'||pathname.startsWith('/app/');if(protectedRoute&&authenticated===null)return <div className="route-loading" aria-live="polite">Cargando tu espacio de trabajo...</div>;if(protectedRoute&&!authenticated)return <AuthPage redirect={pathname+window.location.search}/>;if((pathname==='/login'||pathname==='/register')&&authenticated)return <Landing/>;if(pathname==='/login')return <AuthPage/>;if(pathname==='/register')return <AuthPage register/>;if(protectedRoute)return <Dashboard/>;if(pathname!=='/')return <div className="not-found"><Brand/><h1>Pagina no encontrada</h1><p>Revisa la direccion o vuelve al inicio de ASTRA.</p><a className="button button-primary" href="/">Ir al inicio <ArrowRight size={16}/></a></div>;return <Landing/>;}

createRoot(document.getElementById('root')!).render(<App />);
